/**
 * Section 02 (15大特典) の詳細スクリーンショット取得
 */
import { chromium } from "playwright";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const URL = "https://ah-c.bytech.jp/?uid=01KM8AJKHWVPCE85EYCHP6BRKH";
const OUT = path.join(ROOT, "docs", "design-references");

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();

// Google Fonts をブロックしてタイムアウト回避
await page.route("**fonts.googleapis.com**", (r) => r.abort());
await page.route("**fonts.gstatic.com**", (r) => r.abort());

await page.setViewportSize({ width: 1440, height: 900 });
await page.goto(URL, { waitUntil: "domcontentloaded", timeout: 30000 });

// 少し待ってからスクロールして lazy load 誘発
await page.waitForTimeout(2000);

// ゆっくりスクロール
await page.evaluate(async () => {
  await new Promise((resolve) => {
    let y = 0;
    const step = () => {
      window.scrollTo(0, y);
      y += 400;
      if (y < document.body.scrollHeight) requestAnimationFrame(step);
      else resolve();
    };
    step();
  });
});
await page.waitForTimeout(1500);
await page.evaluate(() => window.scrollTo(0, 0));
await page.waitForTimeout(500);

// セクションを探してスクリーンショット
// Section 02 は Hero の直下
const sections = await page.evaluate(() => {
  const all = [...document.querySelectorAll("section, .section, [class*='section'], [id*='benefit'], [id*='present'], [id*='gift']")];
  return all.slice(0, 10).map((el, i) => {
    const rect = el.getBoundingClientRect();
    return {
      index: i,
      tag: el.tagName,
      id: el.id,
      className: el.className.slice(0, 80),
      top: Math.round(window.scrollY + rect.top),
      height: Math.round(rect.height),
    };
  });
});
console.log("Sections found:", JSON.stringify(sections, null, 2));

// Section 02 は約 Hero の下から始まるはず
// Hero の高さを取得
const heroHeight = await page.evaluate(() => {
  const hero = document.querySelector("section");
  return hero ? hero.getBoundingClientRect().height : 800;
});
console.log("Hero height:", heroHeight);

// セクションを上から 3 つ分クロップ
// デスクトップ全幅キャプチャ（section 02 付近）
await page.setViewportSize({ width: 1440, height: 1200 });
await page.evaluate((h) => window.scrollTo(0, h), Math.round(heroHeight));
await page.waitForTimeout(500);

await page.screenshot({
  path: path.join(OUT, "section-02-15tokusen-desktop.png"),
  clip: { x: 0, y: 0, width: 1440, height: 1200 },
});
console.log("Saved section-02 desktop screenshot");

// さらに下のセクション
await page.evaluate((h) => window.scrollTo(0, h * 2), Math.round(heroHeight));
await page.waitForTimeout(500);
await page.screenshot({
  path: path.join(OUT, "section-02-15tokusen-desktop-2.png"),
  clip: { x: 0, y: 0, width: 1440, height: 1200 },
});
console.log("Saved section-02 desktop screenshot (2)");

// モバイル
await page.setViewportSize({ width: 390, height: 844 });
await page.evaluate((h) => window.scrollTo(0, h), Math.round(heroHeight * 1.5));
await page.waitForTimeout(500);
await page.screenshot({
  path: path.join(OUT, "section-02-15tokusen-mobile.png"),
  clip: { x: 0, y: 0, width: 390, height: 844 },
});
console.log("Saved section-02 mobile screenshot");

await browser.close();
console.log("Done");
