  });
});
fs.writeFileSync(
  path.join(ROOT, "docs", "research", "DOM_STRUCTURE.json"),
  JSON.stringify(structure, null, 2)
);
console.log("Saved DOM_STRUCTURE.json");
console.log(JSON.stringify(structure.slice(0, 10), null, 2));

