/**
 * Elementor セクションごとにスクリーンショット
 */
import { chromium } from "playwright";
import path from "path";
import { fileURLToPath } from "url";
import fs from "fs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const URL = "https://ah-c.bytech.jp/?uid=01KM8AJKHWVPCE85EYCHP6BRKH";
const OUT = path.join(ROOT, "docs", "design-references", "sections");
fs.mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.route("**fonts.googleapis.com**", (r) => r.abort());
await page.route("**fonts.gstatic.com**", (r) => r.abort());
await page.setViewportSize({ width: 1440, height: 900 });
await page.goto(URL, { waitUntil: "networkidle", timeout: 30000 });
await page.waitForTimeout(2000);

// lazy load
await page.evaluate(async () => {
  await new Promise((resolve) => {
    let y = 0;
    const step = () => {
      window.scrollTo(0, y);
      y += 400;
      if (y < document.body.scrollHeight) setTimeout(step, 30);
      else { window.scrollTo(0, 0); resolve(); }
    };
    step();
  });
});
await page.waitForTimeout(2000);
await page.evaluate(() => window.scrollTo(0, 0));
await page.waitForTimeout(500);

// Elementor トップレベルセクション取得
const sections = await page.evaluate(() => {
  // Elementor の top-level section は data-element_type="section" or "container"
  const els = document.querySelectorAll(
    "[data-element_type='section'], [data-element_type='container']"
  );
  return [...els]
    .filter((el) => {
      // トップレベルのみ（親が Elementor section でないもの）
      const parent = el.closest("[data-element_type='section'], [data-element_type='container']");
      return !parent || parent === el;
    })
    .map((el, i) => {
      return {
        index: i,
        id: el.id,
        offsetTop: el.offsetTop,
        height: el.offsetHeight,
        firstText: el.innerText?.slice(0, 100).replace(/\s+/g, " ").trim() || "",
        elementType: el.dataset.elementType,
      };
    });
});

// 実際の全 Elementor top-level section
const allTopSections = await page.evaluate(() => {
  const all = document.querySelectorAll("[data-element_type]");
  const result = [];
  for (const el of all) {
    const parent = el.parentElement?.closest("[data-element_type]");
    if (!parent) {
      result.push({
        id: el.id,
        type: el.dataset.elementType,
        offsetTop: el.offsetTop,
        height: el.offsetHeight,
        firstText: el.innerText?.slice(0, 80).replace(/\s+/g, " ").trim() || "",
      });
    }
  }
  return result;
});

console.log("Top-level Elementor elements:", allTopSections.length);
fs.writeFileSync(
  path.join(ROOT, "docs", "research", "ELEMENTOR_SECTIONS.json"),
  JSON.stringify(allTopSections, null, 2)
);

// 各セクションのスクリーンショット (最初の 15 個)
for (let i = 0; i < Math.min(15, allTopSections.length); i++) {
  const sec = allTopSections[i];
  if (sec.height < 50) continue; // 小さすぎるスキップ

  // スクロールしてセクションを viewport に
  await page.evaluate((y) => window.scrollTo(0, y), Math.max(0, sec.offsetTop - 20));
  await page.waitForTimeout(300);

  const clipH = Math.min(sec.height + 40, 1200);
  await page.screenshot({
    path: path.join(OUT, `sec-${String(i).padStart(2, "0")}-top${sec.offsetTop}.png`),
    clip: { x: 0, y: 0, width: 1440, height: clipH },
  });
  console.log(`sec-${i}: offsetTop=${sec.offsetTop} h=${sec.height} | ${sec.firstText.slice(0, 50)}`);
}

await browser.close();
console.log("Done. Sections saved to:", OUT);
