/**
 * スクロールコンテナを特定してセクションキャプチャ
 */
import { chromium } from "playwright";
import path from "path";
import { fileURLToPath } from "url";
import fs from "fs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const URL = "https://ah-c.bytech.jp/?uid=01KM8AJKHWVPCE85EYCHP6BRKH";
const OUT = path.join(ROOT, "docs", "design-references", "sections2");
fs.mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.route("**fonts.googleapis.com**", (r) => r.abort());
await page.route("**fonts.gstatic.com**", (r) => r.abort());
await page.setViewportSize({ width: 1440, height: 900 });
await page.goto(URL, { waitUntil: "networkidle", timeout: 30000 });
await page.waitForTimeout(3000);

// スクロールコンテナを探す
const containerInfo = await page.evaluate(() => {
  const candidates = [...document.querySelectorAll("*")].filter((el) => {
    const style = getComputedStyle(el);
    const overflow = style.overflow + style.overflowY;
    return (overflow.includes("scroll") || overflow.includes("auto")) &&
      el.scrollHeight > window.innerHeight * 2;
  });
  return candidates.map((el) => ({
    tag: el.tagName,
    id: el.id,
    classes: el.className?.slice(0, 60) || "",
    scrollHeight: el.scrollHeight,
    overflow: getComputedStyle(el).overflow,
    overflowY: getComputedStyle(el).overflowY,
  }));
});
console.log("Scroll containers:", JSON.stringify(containerInfo, null, 2));

// ページを滑らかにスクロールしてスクリーンショット (lazy load後)
// まず全体を scrollBy で走査
await page.evaluate(async () => {
  // window スクロール試行
  await new Promise((resolve) => {
    let y = 0;
    const max = document.body.scrollHeight;
    const step = () => {
      window.scrollTo(0, y);
      y += 300;
      if (y <= max) setTimeout(step, 20);
      else resolve();
    };
    step();
  });
});
await page.waitForTimeout(1000);

// キーボードの Home で先頭へ
await page.keyboard.press("Home");
await page.waitForTimeout(500);

// 先頭から PageDown で進む
const pageH = await page.evaluate(() => Math.max(document.body.scrollHeight, document.documentElement.scrollHeight));
console.log("page scroll height:", pageH);

// Page Downで順に進めてスクリーンショット
const count = Math.ceil(pageH / 800) + 2;
for (let i = 0; i < Math.min(count, 25); i++) {
  const scrollY = i * 800;
  // キーボードスクロールより確実な方法
  await page.evaluate((y) => {
    window.scroll({ top: y, behavior: "instant" });
    // 念のため scrollable container も
    const scrollable = [...document.querySelectorAll("*")].find((el) => el.scrollHeight > 5000);
    if (scrollable && scrollable !== document.body) scrollable.scrollTop = y;
  }, scrollY);
  await page.waitForTimeout(300);

  const currentScroll = await page.evaluate(() => ({
    windowY: window.scrollY,
    documentY: document.documentElement.scrollTop,
    bodyY: document.body.scrollTop,
  }));

  await page.screenshot({
    path: path.join(OUT, `scroll-${String(i).padStart(2,"0")}-target${scrollY}.png`),
    clip: { x: 0, y: 0, width: 1440, height: 900 },
  });
  console.log(`[${i}] target=${scrollY} actual=${JSON.stringify(currentScroll)}`);
}

await browser.close();
