/**
 * 15大特典セクションのアイテム詳細抽出
 */
import { chromium } from "playwright";
import path from "path";
import { fileURLToPath } from "url";
import fs from "fs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const URL = "https://ah-c.bytech.jp/?uid=01KM8AJKHWVPCE85EYCHP6BRKH";

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.route("**fonts.googleapis.com**", (r) => r.abort());
await page.route("**fonts.gstatic.com**", (r) => r.abort());
await page.setViewportSize({ width: 1440, height: 900 });
await page.goto(URL, { waitUntil: "domcontentloaded", timeout: 30000 });
await page.waitForTimeout(3000);

// lazy load
for (let y = 0; y <= 18000; y += 300) {
  await page.evaluate((sy) => window.scrollTo(0, sy), y);
  await page.waitForTimeout(15);
}
await page.waitForTimeout(1500);
await page.evaluate(() => window.scrollTo(0, 800));
await page.waitForTimeout(600);

// Section 02 の全 img 要素と背景画像を取得
const allImages = await page.evaluate(() => {
  const imgs = [...document.querySelectorAll("img")].map((img) => {
    const r = img.getBoundingClientRect();
    return {
      type: "img",
      src: img.src,
      alt: img.alt || "",
      w: Math.round(r.width),
      h: Math.round(r.height),
      absTop: Math.round(r.top + window.scrollY),
    };
  });

  // background-image を持つ要素
  const bgEls = [...document.querySelectorAll("*")].filter((el) => {
    const bg = getComputedStyle(el).backgroundImage;
    return bg && bg !== "none" && bg.includes("url(") && !bg.includes("gradient");
  }).map((el) => {
    const r = el.getBoundingClientRect();
    const bg = getComputedStyle(el).backgroundImage;
    const url = bg.match(/url\(['"]?(.*?)['"]?\)/)?.[1] || "";
    return {
      type: "bg",
      src: url,
      w: Math.round(r.width),
      h: Math.round(r.height),
      absTop: Math.round(r.top + window.scrollY),
    };
  });

  return [...imgs, ...bgEls]
    .filter((x) => x.absTop > 700 && x.absTop < 2500 && x.w > 50)
    .sort((a, b) => a.absTop - b.absTop);
});

console.log("Images in range 700-2500px:");
allImages.forEach((img) => {
  console.log(`  [y=${img.absTop}] ${img.type} ${img.w}x${img.h} | ${img.alt || ""} | ${img.src?.split("/").pop()}`);
});

// テキスト要素も全部取得 (絶対座標)
const allTexts = await page.evaluate(() => {
  const result = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const text = node.textContent?.trim();
    if (!text || text.length < 2) continue;
    const parent = node.parentElement;
    const r = parent?.getBoundingClientRect();
    if (!r) continue;
    const absTop = Math.round(r.top + window.scrollY);
    if (absTop > 700 && absTop < 2500 && r.width > 20) {
      result.push({ text, tag: parent?.tagName, absTop });
    }
  }
  return result;
});

console.log("\nTexts in range 700-2500px:");
allTexts.forEach((t) => {
  if (!t.text.includes("{") && !t.text.includes("function") && t.text.length < 80) {
    console.log(`  [y=${t.absTop}] ${t.tag} | ${t.text}`);
  }
});

fs.writeFileSync(
  path.join(ROOT, "docs", "research", "gifts-extraction.json"),
  JSON.stringify({ images: allImages, texts: allTexts.filter((t) => !t.text.includes("function")) }, null, 2)
);
console.log("\nSaved gifts-extraction.json");
await browser.close();
