/**
 * DOM の主要構造をダンプして section 境界を特定
 */
import { chromium } from "playwright";
import path from "path";
import { fileURLToPath } from "url";
import fs from "fs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const URL = "https://ah-c.bytech.jp/?uid=01KM8AJKHWVPCE85EYCHP6BRKH";

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.route("**fonts.googleapis.com**", (r) => r.abort());
await page.route("**fonts.gstatic.com**", (r) => r.abort());
await page.setViewportSize({ width: 1440, height: 900 });
await page.goto(URL, { waitUntil: "networkidle", timeout: 30000 });
await page.waitForTimeout(3000);

// メインコンテンツのHTMLを取得（最初の 8000 文字）
const html = await page.evaluate(() => {
  const main = document.querySelector(".elementor-section-wrap") ||
    document.querySelector(".e-con-inner") ||
    document.querySelector(".elementor") ||
    document.body;
  return main.innerHTML.slice(0, 10000);
});

fs.writeFileSync(
  path.join(ROOT, "docs", "research", "page-html-snippet.html"),
  html
);
console.log("HTML snippet saved");

// 全要素のうち、offsetTop が前の要素と 200px 以上離れており、height > 300px のものを section とみなす
const sectionBoundaries = await page.evaluate(() => {
  const all = [...document.querySelectorAll("*")];
  const candidates = all.filter((el) => {
    return el.offsetHeight > 300 &&
      el.offsetWidth > 800 &&
      el.children.length > 0 &&
      el.innerText?.length > 20;
  });

  // offsetTop でソート
  candidates.sort((a, b) => a.offsetTop - b.offsetTop);

  // 重複排除
  const result = [];
  let lastTop = -500;
  for (const el of candidates) {
    if (el.offsetTop - lastTop > 200) {
      result.push({
        tag: el.tagName,
        id: el.id,
        classes: el.className?.slice(0, 60) || "",
        offsetTop: el.offsetTop,
        height: el.offsetHeight,
        text: el.innerText?.slice(0, 80).replace(/\s+/g, " ").trim() || "",
      });
      lastTop = el.offsetTop;
    }
  }
  return result.slice(0, 30);
});

console.log(`Section boundaries: ${sectionBoundaries.length}`);
sectionBoundaries.forEach((s, i) => {
  console.log(`[${String(i).padStart(2,"0")}] top=${s.offsetTop} h=${s.height} ${s.id || s.classes.split(" ")[0]} | ${s.text.slice(0,60)}`);
});

fs.writeFileSync(
  path.join(ROOT, "docs", "research", "SECTION_BOUNDARIES.json"),
  JSON.stringify(sectionBoundaries, null, 2)
);

await browser.close();
