/**
 * 背景色の変化でセクション境界を検出 + スクロール位置でスクリーンショット
 */
import { chromium } from "playwright";
import path from "path";
import { fileURLToPath } from "url";
import fs from "fs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const URL = "https://ah-c.bytech.jp/?uid=01KM8AJKHWVPCE85EYCHP6BRKH";
const OUT = path.join(ROOT, "docs", "design-references", "sections");
fs.mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
await page.route("**fonts.googleapis.com**", (r) => r.abort());
await page.route("**fonts.gstatic.com**", (r) => r.abort());
await page.setViewportSize({ width: 1440, height: 900 });
await page.goto(URL, { waitUntil: "networkidle", timeout: 30000 });
await page.waitForTimeout(3000);

// lazy load
await page.evaluate(async () => {
  await new Promise((resolve) => {
    let y = 0;
    const step = () => {
      window.scrollTo(0, y);
      y += 400;
      if (y < document.body.scrollHeight) setTimeout(step, 30);
      else { window.scrollTo(0, 0); resolve(); }
    };
    step();
  });
});
await page.waitForTimeout(2000);
await page.evaluate(() => window.scrollTo(0, 0));
await page.waitForTimeout(500);

// 全要素で getBoundingClientRect (スクロールY=0時) を使って位置を調べる
// ページ全体を2px x 1440 でサンプリングして背景色の変化点を探す
const pageH = await page.evaluate(() => document.body.scrollHeight);
console.log("Page height:", pageH);

// y=0 からページ高さまで 1px 刻みで中心 x=720 の要素を取得してトップ位置を特定
const boundaries = await page.evaluate((pageH) => {
  // 代わりに: elementFromPoint を使ってスクロールY=0ベースで調べる
  // まず全要素の中で h>200 & w>1000 のものを getBoundingClientRect で位置取得
  const all = [...document.querySelectorAll("*")];
  const large = all.filter((el) => {
    const r = el.getBoundingClientRect();
    return r.height > 200 && r.width > 800;
  });
  // スクロールY込みの top = getBoundingClientRect().top + window.scrollY
  large.sort((a, b) => {
    const aTop = a.getBoundingClientRect().top + window.scrollY;
    const bTop = b.getBoundingClientRect().top + window.scrollY;
    return aTop - bTop;
  });

  const result = [];
  let lastAbsTop = -500;
  for (const el of large) {
    const r = el.getBoundingClientRect();
    const absTop = Math.round(r.top + window.scrollY);
    if (absTop - lastAbsTop > 150) {
      const bg = getComputedStyle(el).backgroundColor;
      if (bg !== "rgba(0, 0, 0, 0)" && bg !== "transparent") {
        result.push({
          tag: el.tagName,
          id: el.id,
          classes: el.className?.slice?.(0, 60) || "",
          absTop,
          height: Math.round(r.height),
          bg,
          text: el.innerText?.slice(0, 80).replace(/\s+/g, " ").trim() || "",
        });
        lastAbsTop = absTop;
      }
    }
  }
  return result.slice(0, 30);
}, pageH);

console.log(`Found ${boundaries.length} boundaries with backgrounds:`);
boundaries.forEach((s, i) => {
  console.log(`[${String(i).padStart(2,"0")}] y=${s.absTop} h=${s.height} bg=${s.bg} | ${s.text.slice(0,55)}`);
});

fs.writeFileSync(
  path.join(ROOT, "docs", "research", "BG_BOUNDARIES.json"),
  JSON.stringify(boundaries, null, 2)
);

// スクリーンショット: 各境界点
for (let i = 0; i < Math.min(boundaries.length, 25); i++) {
  const b = boundaries[i];
  const scrollY = Math.max(0, b.absTop - 10);
  await page.evaluate((y) => window.scrollTo(0, y), scrollY);
  await page.waitForTimeout(200);
  const h = Math.min(b.height + 20, 1200);
  await page.screenshot({
    path: path.join(OUT, `bg-sec-${String(i).padStart(2,"0")}-y${b.absTop}.png`),
    clip: { x: 0, y: 0, width: 1440, height: h },
  });
}
console.log("Screenshots saved to", OUT);

await browser.close();
