const sec03Content = await page.evaluate(() => {
  const allText = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const text = node.textContent?.trim();
    if (text && text.length > 2) {
      const parent = node.parentElement;
      const rect = parent?.getBoundingClientRect();
      if (rect && rect.top >= -100 && rect.top <= 950) {
        allText.push({ text, tag: parent?.tagName, top: Math.round(rect.top) });
      }
    }
  }
  return allText;
});

const sec03Images = await page.evaluate(() => {
  return [...document.querySelectorAll("img")].filter((img) => {
    const r = img.getBoundingClientRect();
    return r.top >= -100 && r.top <= 950 && r.width > 30;
  }).map((img) => ({
    src: img.src,
    alt: img.alt,
    top: Math.round(img.getBoundingClientRect().top),
    w: Math.round(img.getBoundingClientRect().width),
  }));
});

