const ASSETS = [
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/KV2_11zon-1024x589.webp", dest: "public/images/sec04/students-grid2.webp" },
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/%E5%B0%BE%E5%B4%8E%E3%81%95%E3%82%93-1-1024x890.webp", dest: "public/images/sec04/ozaki.webp" },
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/%E9%A3%AF%E7%94%B0%E3%81%95%E3%82%93-1024x890.webp", dest: "public/images/sec04/iida.webp" },
  // 上原さん (sec02 と共有)
  // ロゴ.svg (ロゴ)
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/%E3%83%AD%E3%82%B4.svg", dest: "public/images/common/logo.svg" },
];

for (const asset of ASSETS) {
  const dest = path.join(ROOT, asset.dest);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  if (fs.existsSync(dest)) { console.log(`[skip] ${asset.dest}`); continue; }
  process.stdout.write(`[fetch] ${path.basename(asset.dest)} ... `);
  try {
    const res = await fetch(asset.url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    fs.writeFileSync(dest, buf);
    console.log(`OK (${(buf.length/1024).toFixed(1)} KB)`);
  } catch(e) { console.log(`FAILED: ${e.message}`); }
}
console.log("Done.");
