const ASSETS = [
  // Section 05: 2ヶ月でこう変わる
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/2%E3%83%B6%E6%9C%88%E3%81%A7%E3%81%93%E3%81%86%E5%A4%89%E3%82%8F%E3%82%8B-1.svg", dest: "public/images/sec05/title.svg" },
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/%E7%9F%A2%E5%8D%B0.svg", dest: "public/images/sec05/arrow.svg" },
  // アートボード – 9_3（速水さん的証言カード）
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/%E3%82%A2%E3%83%BC%E3%83%88%E3%83%9C%E3%83%BC%E3%83%89-%E2%80%93-9_3.webp", dest: "public/images/sec05/interview-card.webp" },
  // Section 06: 悩みリスト
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/%E3%81%8A%E6%82%A9%E3%81%BF%E3%83%AA%E3%82%B9%E3%83%88-1-1024x981.webp", dest: "public/images/sec06/worry-list.webp" },
  // Section 08: formula / 冒頭コピー
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/%E5%86%92%E9%A0%AD%E3%82%B3%E3%83%94%E3%83%BC.svg", dest: "public/images/sec08/formula.svg" },
  // KV1
  { url: "https://ah-c.bytech.jp/wp-content/uploads/2026/01/KV-1-1024x324.webp", dest: "public/images/sec08/kv1.webp" },
];

for (const asset of ASSETS) {
  const dest = path.join(ROOT, asset.dest);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  if (fs.existsSync(dest)) { console.log(`[skip] ${asset.dest}`); continue; }
  process.stdout.write(`[fetch] ${path.basename(asset.dest)} ... `);
  try {
    const res = await fetch(asset.url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    fs.writeFileSync(dest, buf);
    console.log(`OK (${(buf.length/1024).toFixed(1)} KB)`);
  } catch(e) { console.log(`FAILED: ${e.message}`); }
}
console.log("Done.");
