574	    const challengeInput = page.locator('input[data-testid="ocfEnterTextTextInput"], input[name="text"]').first();
575	    await challengeInput.fill(credentials.challengeIdentifier);
576	    await clickFirstVisibleEnabled(
577	      page.locator('button, [role="button"]').filter({ hasText: /^(Next|次へ)$/ }),
578	      'X login challenge Next button',
579	    );
580	    await sleep(700);
581	    state = await waitForPasswordOrChallenge(page);
582	  }
