303	      const fontSizeFor = (chunk) => `${chunk.fontSize || (chunk.type === "connector" ? 38 : chunk.type === "list" ? 44 : 48)}px`;
304	      const applyClipReveal = (element, prefix, item, progress) => {
305	        const hidden = `${(1 - progress) * 100}%`;
306	        const direction = item.direction || "left-to-right";
307	        if (direction === "top-to-bottom") {
308	          element.style.setProperty(`--${prefix}-clip-bottom`, hidden);
309	        } else if (direction === "right-to-left") {
310	          element.style.setProperty(`--${prefix}-clip-left`, hidden);
311	        } else if (direction === "bottom-to-top") {
312	          element.style.setProperty(`--${prefix}-clip-top`, hidden);
313	        } else {
314	          element.style.setProperty(`--${prefix}-clip-right`, hidden);
315	        }
316	      };
317	      const applyEnterMotion = (element, prefix, item, progress) => {
318	        if (item.enter === "fade") {
319	          return;
320	        }
321	
322	        if (item.enter === "pop") {
323	          element.style.setProperty(`--${prefix}-scale`, String(0.84 + progress * 0.16));
324	        } else if (item.enter === "rise") {
325	          element.style.setProperty(`--${prefix}-y`, `${(1 - progress) * 32}px`);
326	          element.style.setProperty(`--${prefix}-scale`, String(0.96 + progress * 0.04));
327	        } else if (item.enter === "draw") {
328	          applyClipReveal(element, prefix, item, progress);
329	          element.style.setProperty(`--${prefix}-scale`, String(0.98 + progress * 0.02));
330	        } else if (item.enter === "wipe") {
331	          applyClipReveal(element, prefix, item, progress);
332	        } else if (item.enter === "slide") {
333	          const fromX = item.fromX ?? 40;
334	          const fromY = item.fromY ?? 0;
335	          element.style.setProperty(`--${prefix}-x`, `${(1 - progress) * fromX}px`);
336	          element.style.setProperty(`--${prefix}-y`, `${(1 - progress) * fromY}px`);
337	        } else if (item.enter === "zoom") {
338	          element.style.setProperty(`--${prefix}-scale`, String(0.7 + progress * 0.3));
339	        }
340	      };
341	      const createGeneratedLayer = (imageLayer, localFrame) => {
342	        const start = imageLayer.at ?? imageLayer.start ?? 0;
343	        const end = imageLayer.end ?? Number.POSITIVE_INFINITY;
344	        const elapsed = localFrame - start;
345	        if (elapsed < 0 || localFrame >= end) {
346	          return null;
347	        }
348	
349	        const progress = easeOut(elapsed / (imageLayer.duration || 18));
350	        const element = document.createElement("img");
351	        element.className = "generated-layer";
352	        element.src = resolveAssetSrc(imageLayer.src);
353	        element.alt = imageLayer.alt || "";
354	        element.decoding = "async";
355	        element.draggable = false;
356	        element.style.left = `${imageLayer.x}px`;
357	        element.style.top = `${imageLayer.y}px`;
358	        element.style.width = `${imageLayer.w}px`;
359	        element.style.height = `${imageLayer.h}px`;
360	        element.style.objectFit = imageLayer.fit || "contain";
361	        element.style.zIndex = imageLayer.zIndex || 0;
