363	          element.style.filter = "none";
364	        }
365	        element.style.setProperty("--layer-opacity", String((imageLayer.opacity ?? 1) * progress));
366	        element.style.setProperty("--layer-rotate", `${imageLayer.rotate || 0}deg`);
367	        applyEnterMotion(element, "layer", imageLayer, progress);
368	        return element;
369	      };
370	      const createChunk = (chunk, localFrame) => {
371	        const elapsed = localFrame - chunk.at;
372	        if (elapsed < 0) {
373	          return null;
374	        }
375	
376	        const progress = easeOut(elapsed / 16);
377	        const element = document.createElement("div");
378	        element.className = `chunk chunk-${chunk.type}`;
379	        element.style.left = `${chunk.x}px`;
380	        element.style.top = `${chunk.y}px`;
