    var sheet = ss.getSheetByName(SPECIAL_SHEET_8_NAME_);
    if (!sheet) {
      throw new Error("対象シートが見つかりません: " + SPECIAL_SHEET_8_NAME_);
    }

    var result = applyDuplicateStatusToSheet_(sheet);
    SpreadsheetApp.getUi().alert(
      "重複チェック完了\n" +
      "対象行: " + result.targetRows + "\n" +
      "重複: " + result.duplicateRows + "\n" +
      "1S予定: " + result.plannedRows + "\n" +
      "維持: " + result.keptRows
    );
  } catch (err) {
    debugLogError_(debug, err, "runForm8DuplicateCheck");
    SpreadsheetApp.getUi().alert("重複チェックに失敗しました: " + err);
    throw err;
  } finally {
    if (lock.hasLock()) lock.releaseLock();
  }
}

function doPost(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var debug = ss.getSheetByName(DEBUG_SHEET_NAME_) || ss.insertSheet(DEBUG_SHEET_NAME_);
  var lock = LockService.getDocumentLock();
  var raw = (e && e.postData && e.postData.contents) ? e.postData.contents : "";

  try {
    lock.waitLock(10000);

    var p = (e && e.parameter) ? e.parameter : {};
    var payload = parseRequestPayload_(raw);

    // 固定列（先頭3列）
    var sentAt = resolveSentAt_(p, payload);
    var uid = pickFirstNonEmpty_([
      p.uid,
      payload.uid,
      getNestedValue_(payload, ["user_data", "uid"])
    ]);
    var snsname = pickFirstNonEmpty_([
      p["user_data[snsname]"],
      p["user_data[linename]"],
      p.snsname,
      getNestedValue_(payload, ["user_data", "snsname"]),
      getNestedValue_(payload, ["user_data", "linename"])
    ]);
    var referrerName = resolveReferrerName_(ss, extractReferrerCode_(p, payload));

    // シート（form_nameベース）
    var sheet = getOrCreateSheet_(
      ss,
      sheetNameFromFormName_(pickFirstNonEmpty_([p.form_name, payload.form_name, "unknown"]))
    );

    // form_data（送信順）
    var parsed = parseOrderedFormData_(raw);
    var keysOrder = parsed.keysOrder;   // 送信順のキー配列
    var valuesMap = parsed.valuesMap;   // { key: [v1,v2...] }

    // ヘッダー準備と form_data キー -> 列の安定マッピング
    var columnMap = ensureHeaderAndGetColumnMap_(sheet, keysOrder);
    var headerInfo = getSheetHeaderInfo_(sheet);

    // データ行を「キーに対応する列」で作る
    var lastCol = Math.max(sheet.getLastColumn(), headerInfo.values.length);
    var row = [];
    for (var i = 0; i < lastCol; i++) row.push("");

    setRowValueByHeaderName_(row, headerInfo, "date", sentAt);
    setRowValueByHeaderName_(row, headerInfo, "uid", uid);
    setRowValueByHeaderName_(row, headerInfo, "snsname", snsname);

    // form_data はヘッダー表示名ではなく内部キー対応で書き込む
    for (var j = 0; j < keysOrder.length; j++) {
      var k = keysOrder[j];
      var arr = valuesMap[k] || [];
      var col = columnMap[k] - 1; // 1-based -> 0-based
      if (col < 0) continue;
      if (col >= row.length) break;
      row[col] = arr.join("\n"); // ファイル複数は改行、チェックボックスは元がカンマ文字列ならそのまま
    }

    applySpecialSheetFieldMapping_(sheet, headerInfo, row, valuesMap);
    applySpecialSheetStatus_(sheet, headerInfo, row, uid);
    setRowValueByHeaderName_(row, headerInfo, REFERRER_HEADER_, referrerName);

    sheet.getRange(sheet.getLastRow() + 1, 1, 1, row.length).setValues([row]);
    return ContentService.createTextOutput("OK");

  } catch (err) {
    debugLogError_(debug, err, raw);
    return ContentService.createTextOutput("NG");
  } finally {
    if (lock.hasLock()) lock.releaseLock();
  }
}

/**
 * 1行目の表示名は維持しつつ、note に form_data の内部キーを保存して列マッピングを安定化する。
 * 既存シートで note が無い列は、当面は現在の列順から補完して移行する。
 */
function ensureHeaderAndGetColumnMap_(sheet, keysOrder) {
  var baseLen = BASE_HEADERS_.length;
  var lastCol = Math.max(sheet.getLastColumn(), baseLen);
  var headerValues = [];
  var headerNotes = [];
  var hasHeader = false;

  if (sheet.getLastColumn() > 0) {
    var range = sheet.getRange(1, 1, 1, lastCol);
    headerValues = range.getValues()[0];
    headerNotes = range.getNotes()[0];
  } else {
    for (var i = 0; i < lastCol; i++) {
      headerValues.push("");
      headerNotes.push("");
    }
  }

  for (var j = 0; j < headerValues.length; j++) {
    if (headerValues[j] !== "") {
      hasHeader = true;
      break;
    }
  }

  if (!hasHeader) {
    headerValues = BASE_HEADERS_.concat(keysOrder);
    headerNotes = buildHeaderNotes_(headerValues.length, keysOrder);
    sheet.getRange(1, 1, 1, headerValues.length).setValues([headerValues]);
    sheet.getRange(1, 1, 1, headerNotes.length).setNotes([headerNotes]);
    return buildIncomingColumnMap_(keysOrder, baseLen);
  }

  while (headerValues.length < baseLen) headerValues.push("");
  while (headerNotes.length < headerValues.length) headerNotes.push("");

  for (var baseIndex = 0; baseIndex < baseLen; baseIndex++) {
    if (!headerValues[baseIndex]) headerValues[baseIndex] = BASE_HEADERS_[baseIndex];
  }

  var keyToCol = {};
  for (var colIndex = baseLen; colIndex < headerValues.length; colIndex++) {
    var existingKey = headerKeyFromNote_(headerNotes[colIndex]);

    if (!existingKey) {
      existingKey = keysOrder[colIndex - baseLen] || String(headerValues[colIndex] || "").trim();
      if (existingKey) headerNotes[colIndex] = HEADER_KEY_PREFIX_ + existingKey;
    }

    if (existingKey && !keyToCol[existingKey]) {
      keyToCol[existingKey] = colIndex + 1;
    }
  }

  for (var incomingIndex = 0; incomingIndex < keysOrder.length; incomingIndex++) {
    var key = keysOrder[incomingIndex];
    if (keyToCol[key]) continue;

    headerValues.push(key);
    headerNotes.push(HEADER_KEY_PREFIX_ + key);
    keyToCol[key] = headerValues.length;
  }

  sheet.getRange(1, 1, 1, headerValues.length).setValues([headerValues]);
  sheet.getRange(1, 1, 1, headerNotes.length).setNotes([headerNotes]);

  return keyToCol;
}

function getSheetHeaderInfo_(sheet) {
  var width = Math.max(sheet.getLastColumn(), BASE_HEADERS_.length);
  var values = [];
  var notes = [];

  if (sheet.getLastColumn() > 0) {
    var range = sheet.getRange(1, 1, 1, width);
    values = range.getValues()[0];
    notes = range.getNotes()[0];
  } else {
    for (var i = 0; i < width; i++) {
      values.push("");
      notes.push("");
    }
  }

  var headerMap = {};
  for (var col = 0; col < values.length; col++) {
    var headerName = normalizeHeaderName_(values[col]);
    if (headerName && !headerMap[headerName]) {
      headerMap[headerName] = col + 1;
    }
  }

  return {
    values: values,
    notes: notes,
    headerMap: headerMap
  };
}

function parseOrderedFormData_(raw) {
  var keysOrder = [];
  var valuesMap = {};
  if (!raw) return { keysOrder: keysOrder, valuesMap: valuesMap };

  var parts = raw.split("&");
  for (var i = 0; i < parts.length; i++) {
    var part = parts[i];
    if (!part) continue;

    var eq = part.indexOf("=");
    var kEnc = (eq >= 0) ? part.slice(0, eq) : part;
    var vEnc = (eq >= 0) ? part.slice(eq + 1) : "";

    var key = safeDecodeURIComponent_(kEnc.replace(/\+/g, " "));
    var val = safeDecodeURIComponent_(vEnc.replace(/\+/g, " "));

    var m = key.match(/^form_data\[(.+)\]$/);
    if (!m) continue;

    // "form34-6][0" / "form34-6][0]" を "form34-6" に正規化
    var innerKey = m[1].replace(/\]\[\d+\]?$/g, "");

    if (!valuesMap[innerKey]) valuesMap[innerKey] = [];
    if (val !== "") valuesMap[innerKey].push(val);

    if (keysOrder.indexOf(innerKey) === -1) keysOrder.push(innerKey);
  }

  return { keysOrder: keysOrder, valuesMap: valuesMap };
}

function sheetNameFromFormName_(formName) {
  var prefix = "form_";
  var maxLen = 100;

  var name = String(formName)
    .replace(/:/g, "：")
    .replace(/[\\\/\?\*\[\]]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (!name) name = "unknown";

  var allow = maxLen - prefix.length;
  if (name.length > allow) name = name.slice(0, allow).trim();

  return prefix + name;
}

function getOrCreateSheet_(ss, name) {
  return ss.getSheetByName(name) || ss.insertSheet(name);
}

function fmt_(d) {
  return Utilities.formatDate(d, TIMEZONE_, "yyyy-MM-dd HH:mm:ss");
}

function resolveSentAt_(params, payload) {
  var dateValue = pickFirstNonEmpty_([
    params.date,
    payload.date,
    getNestedValue_(payload, ["user_data", "date"])
  ]);
  if (dateValue) return String(dateValue);

  var unixtime = pickFirstNonEmpty_([
    params.unixtime,
    payload.unixtime,
    getNestedValue_(payload, ["user_data", "unixtime"])
  ]);
  if (unixtime) return fmt_(new Date(Number(unixtime) * 1000));

  return fmt_(new Date());
}

function safeDecodeURIComponent_(value) {
  try {
    return decodeURIComponent(value);
  } catch (err) {
    return value;
  }
}

function buildHeaderNotes_(length, keysOrder) {
  var notes = [];
  for (var i = 0; i < length; i++) {
    if (i < BASE_HEADERS_.length) {
      notes.push("");
      continue;
    }

    var key = keysOrder[i - BASE_HEADERS_.length] || "";
    notes.push(key ? HEADER_KEY_PREFIX_ + key : "");
  }
  return notes;
}

function buildIncomingColumnMap_(keysOrder, baseLen) {
  var keyToCol = {};
  for (var i = 0; i < keysOrder.length; i++) {
    keyToCol[keysOrder[i]] = baseLen + i + 1;
  }
  return keyToCol;
}

function headerKeyFromNote_(note) {
  if (!note || note.indexOf(HEADER_KEY_PREFIX_) !== 0) return "";
  return note.slice(HEADER_KEY_PREFIX_.length);
}

function setRowValueByHeaderName_(row, headerInfo, headerName, value) {
  var col = findHeaderColumn_(headerInfo, headerName);
  if (!col) return false;

  row[col - 1] = value;
  return true;
}

function applySpecialSheetFieldMapping_(sheet, headerInfo, row, valuesMap) {
  if (sheet.getName() !== SPECIAL_SHEET_8_NAME_) return;

  for (var formLabel in SPECIAL_FORM_HEADER_MAP_) {
    if (!SPECIAL_FORM_HEADER_MAP_.hasOwnProperty(formLabel)) continue;

    var headerName = SPECIAL_FORM_HEADER_MAP_[formLabel];
    var col = findHeaderColumn_(headerInfo, headerName);
    if (!col) continue;

    var key = findFormKeyByLabel_(valuesMap, formLabel);
    if (!key) continue;

    row[col - 1] = (valuesMap[key] || []).join("\n");
  }
}

function applySpecialSheetStatus_(sheet, headerInfo, row, uid) {
  if (sheet.getName() !== SPECIAL_SHEET_8_NAME_) return;

  var duplicateState = getDuplicateStateByUid_(sheet, headerInfo, uid);
  if (!duplicateState.statusCol) {
    throw new Error("form_8 シートで uid 列または 1S 列が見つかりません。1行目を確認してください。");
  }

  var shouldUsePlanned = !duplicateState.isDuplicate || duplicateState.shouldPromoteToPlanned;
  row[duplicateState.statusCol - 1] = shouldUsePlanned ? SPECIAL_STATUS_PLANNED_ : SPECIAL_STATUS_DUPLICATE_;

  var ownerCol = findHeaderColumn_(headerInfo, SPECIAL_OWNER_HEADER_);
  if (ownerCol && shouldUsePlanned) {
    row[ownerCol - 1] = SPECIAL_OWNER_SHO_;
  }
}

function applyDuplicateStatusToSheet_(sheet) {
  var headerInfo = getSheetHeaderInfo_(sheet);
  var uidCol = findHeaderColumn_(headerInfo, "uid");
  var statusCol = findHeaderColumn_(headerInfo, SPECIAL_STATUS_HEADER_);
  var ownerCol = findHeaderColumn_(headerInfo, SPECIAL_OWNER_HEADER_);
  if (!uidCol || !statusCol) {
    throw new Error("uid 列または 1S 列が見つかりません。1行目を確認してください。");
  }

  var lastRow = sheet.getLastRow();
  if (lastRow <= 1) {
    return {
      targetRows: 0,
      duplicateRows: 0,
      plannedRows: 0,
      keptRows: 0
    };
  }

  var width = Math.max(sheet.getLastColumn(), headerInfo.values.length);
  var values = sheet.getRange(2, 1, lastRow - 1, width).getValues();
  var seen = {};
  var statusValues = [];
  var ownerValues = [];
  var duplicateRows = 0;
  var plannedRows = 0;
  var keptRows = 0;

  for (var i = 0; i < values.length; i++) {
    var row = values[i];
    var uid = normalizeUid_(row[uidCol - 1]);
    var currentStatus = normalizeStatus_(row[statusCol - 1]);
    var nextStatus = currentStatus;
    var currentOwner = ownerCol ? String(row[ownerCol - 1] || "").trim() : "";
    var nextOwner = currentOwner;

    if (uid) {
      if (!seen[uid]) {
        seen[uid] = {
          hasActive: false
        };
      }

      if (seen[uid].hasActive) {
        nextStatus = SPECIAL_STATUS_DUPLICATE_;
        duplicateRows += 1;
      } else {
        if (!currentStatus || currentStatus === SPECIAL_STATUS_DUPLICATE_) {
          nextStatus = SPECIAL_STATUS_PLANNED_;
          if (ownerCol) nextOwner = SPECIAL_OWNER_SHO_;
          seen[uid].hasActive = true;
          plannedRows += 1;
        } else if (isActiveFirstStepStatus_(currentStatus)) {
          seen[uid].hasActive = true;
          keptRows += 1;
        } else {
          keptRows += 1;
        }
      }
    } else {
      keptRows += 1;
    }

    statusValues.push([nextStatus]);
    if (ownerCol) ownerValues.push([nextOwner]);
  }

  sheet.getRange(2, statusCol, statusValues.length, 1).setValues(statusValues);
  if (ownerCol) {
    sheet.getRange(2, ownerCol, ownerValues.length, 1).setValues(ownerValues);
  }

  return {
    targetRows: values.length,
    duplicateRows: duplicateRows,
    plannedRows: plannedRows,
    keptRows: keptRows
  };
}

function getDuplicateStateByUid_(sheet, headerInfo, uid) {
  var uidCol = findHeaderColumn_(headerInfo, "uid");
  var statusCol = findHeaderColumn_(headerInfo, SPECIAL_STATUS_HEADER_);
  if (!uidCol || !statusCol) {
    return {
      uidCol: uidCol,
      statusCol: statusCol,
      isDuplicate: false,
      shouldPromoteToPlanned: false
    };
  }

  var normalizedUid = normalizeUid_(uid);
  if (!normalizedUid) {
    return {
      uidCol: uidCol,
      statusCol: statusCol,
      isDuplicate: false,
      shouldPromoteToPlanned: false
    };
  }

  var lastRow = sheet.getLastRow();
  if (lastRow <= 1) {
    return {
      uidCol: uidCol,
      statusCol: statusCol,
      isDuplicate: false,
      shouldPromoteToPlanned: false
    };
  }

  var width = Math.max(uidCol, statusCol);
  var values = sheet.getRange(2, 1, lastRow - 1, width).getValues();
  var hasMatch = false;
  var hasActiveExisting = false;

  for (var i = 0; i < values.length; i++) {
    if (normalizeUid_(values[i][uidCol - 1]) === normalizedUid) {
      hasMatch = true;
      if (isActiveFirstStepStatus_(values[i][statusCol - 1])) {
        hasActiveExisting = true;
        break;
      }
    }
  }

  return {
    uidCol: uidCol,
    statusCol: statusCol,
    isDuplicate: hasMatch,
    shouldPromoteToPlanned: hasMatch && !hasActiveExisting
  };
}

function normalizeHeaderName_(value) {
  return String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
}

function findHeaderColumn_(headerInfo, headerName) {
  var normalized = normalizeHeaderName_(headerName);
  var aliases = HEADER_ALIASES_[normalized] || [headerName];

  for (var i = 0; i < aliases.length; i++) {
    var col = headerInfo.headerMap[normalizeHeaderName_(aliases[i])];
    if (col) return col;
  }

  return 0;
}

function findFormKeyByLabel_(valuesMap, label) {
  var normalizedLabel = normalizeFormLabel_(label);
  for (var key in valuesMap) {
    if (!valuesMap.hasOwnProperty(key)) continue;
    if (normalizeFormLabel_(key) === normalizedLabel) return key;
  }
  return "";
}

function normalizeFormLabel_(value) {
  return String(value || "").replace(/\s+/g, "").trim();
}

function normalizeUid_(value) {
  return String(value || "").replace(/\s+/g, "").trim();
}

function normalizeStatus_(value) {
  return String(value || "").trim();
}

function isActiveFirstStepStatus_(value) {
  var status = normalizeStatus_(value);
  return status === SPECIAL_STATUS_PLANNED_ || status === SPECIAL_STATUS_DONE_;
}

function parseRequestPayload_(raw) {
  if (!raw) return {};

  try {
    return JSON.parse(raw);
  } catch (err) {
    return parseNestedBody_(raw);
  }
}

function parseNestedBody_(raw) {
  var payload = {};
  var parts = String(raw || "").split("&");

  for (var i = 0; i < parts.length; i++) {
    var part = parts[i];
    if (!part) continue;

    var eq = part.indexOf("=");
    var kEnc = (eq >= 0) ? part.slice(0, eq) : part;
    var vEnc = (eq >= 0) ? part.slice(eq + 1) : "";
    var key = safeDecodeURIComponent_(kEnc.replace(/\+/g, " "));
    var value = safeDecodeURIComponent_(vEnc.replace(/\+/g, " "));
    assignNestedValue_(payload, key, value);
  }

  return payload;
}

function assignNestedValue_(target, key, value) {
  var normalized = String(key || "").replace(/\]/g, "");
  var segments = normalized.split("[").filter(Boolean);
  if (!segments.length) return;

  var current = target;
  for (var i = 0; i < segments.length - 1; i++) {
    var segment = segments[i];
    if (!current[segment] || typeof current[segment] !== "object") {
      current[segment] = {};
    }
    current = current[segment];
  }

  current[segments[segments.length - 1]] = value;
}

function getNestedValue_(target, pathSegments) {
  var current = target;

  for (var i = 0; i < pathSegments.length; i++) {
    if (!current || typeof current !== "object") return "";
    current = current[pathSegments[i]];
  }

  return current == null ? "" : current;
}

function pickFirstNonEmpty_(candidates) {
  for (var i = 0; i < candidates.length; i++) {
    var value = candidates[i];
    if (value !== null && value !== undefined && String(value).trim() !== "") {
      return value;
    }
  }

  return "";
}

function extractReferrerCode_(params, payload) {
  return normalizeUid_(pickFirstNonEmpty_([
    params.ref_code,
    params.free2,
    params["user_data[ref_code]"],
    params["user_data[free2]"],
    params["form_data[ref_code]"],
    params["form_data[free2]"],
    payload.ref_code,
    payload.free2,
    getNestedValue_(payload, ["user_data", "ref_code"]),
    getNestedValue_(payload, ["user_data", "free2"]),
    getNestedValue_(payload, ["form_data", "ref_code"]),
    getNestedValue_(payload, ["form_data", "free2"])
  ]));
}

function resolveReferrerName_(spreadsheet, refCode) {
  if (!refCode) return REFERRER_NONE_TEXT_;

  var masterSheet = spreadsheet.getSheetByName(REFERRER_MASTER_SHEET_NAME_);
  if (!masterSheet) {
    throw new Error("紹介者マスタが見つかりません: " + REFERRER_MASTER_SHEET_NAME_);
  }

  var lastRow = masterSheet.getLastRow();
  var lastColumn = masterSheet.getLastColumn();
  if (lastRow < 2 || lastColumn < 1) return REFERRER_NONE_TEXT_;

  var values = masterSheet.getRange(1, 1, lastRow, lastColumn).getDisplayValues();
  var headerMap = buildHeaderMapFromValues_(values[0] || []);
  var codeCol = findHeaderIndex_(headerMap, REFERRER_CODE_HEADERS_, 3);
  var nameCol = findHeaderIndex_(headerMap, REFERRER_NAME_HEADERS_, 2);

  for (var i = 1; i < values.length; i++) {
    var row = values[i];
    if (normalizeUid_(row[codeCol - 1]) === refCode) {
      return normalizeStatus_(row[nameCol - 1]) || REFERRER_NONE_TEXT_;
    }
  }

  return REFERRER_NONE_TEXT_;
}

function buildHeaderMapFromValues_(headerValues) {
  var headerMap = {};

  for (var i = 0; i < headerValues.length; i++) {
    var normalized = normalizeHeaderName_(headerValues[i]);
    if (normalized && !headerMap[normalized]) {
      headerMap[normalized] = i + 1;
    }
  }

  return headerMap;
}

function findHeaderIndex_(headerMap, candidates, fallbackIndex) {
  for (var i = 0; i < candidates.length; i++) {
    var col = headerMap[normalizeHeaderName_(candidates[i])];
    if (col) return col;
  }

  return fallbackIndex;
}

function debugLogError_(debugSheet, err, raw) {
  debugSheet.appendRow([
    fmt_(new Date()),
    "ERROR",
    String(err),
    raw
  ]);
}

prompt_preview:
ちなみに、今使っているGASはこれ。var BASE_HEADERS_ = ["date", "uid", "snsname"];
var HEADER_KEY_PREFIX_ = "form_key:";
var DEBUG_SHEET_NAME_ = "_debug";
var TIMEZONE_ = "Asia/Tokyo";
var SPECIAL_SHEET_8_NAME_ = "form_8：在宅ワーク面談前アンケート";
var SPECIAL_STATUS_HEADER_ = "1S";
var SPECIAL_OWNER_HEADER_ = "1S担当";
var SPECIAL_STATUS_DUPLICATE_ = "重複";
var SPECIAL_STATUS_PLANNED_ = "1S予定";
var SPECIAL_STATUS_DONE_ = "1S済み";
var SPECIAL_OWNER_SHO_ = "Sho";
var HEADER_ALIASES_ = {
  date: ["date", "送信日"],
  uid: ["uid"],
  snsname: ["snsname", "line名", "line 名"]
};
var SPECIAL_FORM_HEADER_MAP_ = {
  "氏名：": "氏名",
  "性別：": "性別",
  "年齢：": "年齢",
  "電話番号：": "電話番号",
  "応募理由（任意）：": "応募理由"
};
var REFERRER_HEADER_ = "アフィリエイター";
var REFERRER_MASTER_SHEET_NAME_ = "アフィリエイター情報";
var REFERRER_CODE_HEADERS_ = ["アフィリエイトコード", "紹介者コード"];
var REFERRER_NAME_HEADERS_ = ["LINE名", "紹介者名(LINE名)", "登録者LINE名", "アフィリエイター"];
var REFERRER_NONE_TEXT_ = "なし";

function doGet() {
  return ContentService.createTextOutput("OK");
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("Webhook Tools")
    .addItem("form_8 の重複チェック", "runForm8DuplicateCheck")
    .addToUi();
}

function runForm8DuplicateCheck() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var debug = ss.getSheetByName(DEBUG_SHEET_NAME_) || ss.insertSheet(DEBUG_SHEET_NAME_);
  var lock = LockService.getDocumentLock();

  try {
    lock.waitLock(10000);

    var sheet = ss.getSheetByName(SPECIAL_SHEET_8_NAME_);
    if (!sheet) {
      throw new Error("対象シートが見つかりません: " + SPECIAL_SHEET_8_NAME_);
    }

    var result = applyDuplicateStatusToSheet_(sheet);
    SpreadsheetApp.getUi().alert(
      "重複チェック完了\n" +
      "対象行: " + result.targetRows + "\n" +
      "重複: " + result.duplicateRows + "\n" +
      "1S予定: " + result.plannedRows + "\n" +
      "維持: " + result.keptRows
    );
  } catch (err) {
    debugLogError_(debug, err, "runForm8DuplicateCheck");
    SpreadsheetApp.getUi().alert("重複チェックに失敗しました: " + err);
    throw err;
  } finally {
    if (lock.hasLock()) lock.releaseLock();
  }
}

function doPost(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var debug = ss.getSheetByName(DEBUG_SHEET_NAME_) || ss.insertSheet(DEBUG_SHEET_NAME_);
  var lock = LockService.getDocumentLock();
  var raw = (e && e.postData && e.postData.contents) ? e.postData.contents : "";

  try {
    lock.waitLock(10000);

    var p = (e && e.parameter) ? e.parameter : {};
    var payload = parseRequestPayload_(raw);

    // 固定列（先頭3列）
    var sentAt = resolveSentAt_(p, payload);
    var uid = pickFirstNonEmpty_([
      p.uid,
      payload.uid,
      getNestedValue_(payload, ["user_data", "uid"])
    ]);
    var snsname = pickFirstNonEmpty_([
      p["user_data[snsname]"],
      p["user_data[linename]"],
      p.snsname,
      getNestedValue_(payload, ["user_data", "snsname"]),
      getNestedValue_(payload, ["user_data", "linename"])
    ]);
    var referrerName = resolveReferrerName_(ss, extractReferrerCode_(p, payload));

    // シート（form_nameベース）
    var sheet = getOrCreateSheet_(
      ss,
      sheetNameFromFormName_(pickFirstNonEmpty_([p.form_name, payload.form_name, "unknown"]))
    );

    // form_data（送信順）
    var parsed = parseOrderedFormData_(raw);
    var keysOrder = parsed.keysOrder;   // 送信順のキー配列
    var valuesMap = parsed.valuesMap;   // { key: [v1,v2...] }

    // ヘッダー準備と form_data キー -> 列の安定マッピング
    var columnMap = ensureHeaderAndGetColumnMap_(sheet, keysOrder);
    var headerInfo = getSheetHeaderInfo_(sheet);

    // データ行を「キーに対応する列」で作る
    var lastCol = Math.max(sheet.getLastColumn(), headerInfo.values.length);
    var row = [];
    for (var i = 0; i < lastCol; i++) row.push("");

    setRowValueByHeaderName_(row, headerInfo, "date", sentAt);
    setRowValueByHeaderName_(row, headerInfo, "uid", uid);
    setRowValueByHeaderName_(row, headerInfo, "snsname", snsname);

    // form_data はヘッダー表示名ではなく内部キー対応で書き込む
    for (var j = 0; j < keysOrder.length; j++) {
      var k = keysOrder[j];
      var arr = valuesMap[k] || [];
      var col = columnMap[k] - 1; // 1-based -> 0-based
      if (col < 0) continue;
      if (col >= row.length) break;
      row[col] = arr.join("\n"); // ファイル複数は改行、チェックボックスは元がカンマ文字列ならそのまま
    }

    applySpecialSheetFieldMapping_(sheet, headerInfo, row, valuesMap);
    applySpecialSheetStatus_(sheet, headerInfo, row, uid);
    setRowValueByHeaderName_(row, headerInfo, REFERRER_HEADER_, referrerName);

    sheet.getRange(sheet.getLastRow() + 1, 1, 1, row.length).setValues([row]);
    return ContentService.createTextOutput("OK");

  } catch (err) {
    debugLogError_(debug, err, raw);
    return ContentService.createTextOutput("NG");
  } finally {
    if (lock.hasLock()) lock.releaseLock();
  }
}

/**
 * 1行目の表示名は維持しつつ、note に form_data の内部キーを保存して列マッピングを安定化する。
 * 既存シートで note が無い列は、当面は現在の列順から補完して移行する。
 */
function ensureHeaderAndGetColumnMap_(sheet, keysOrder) {
  var baseLen = BASE_HEADERS_.length;
  var lastCol = Math.max(sheet.getLastColumn(), baseLen);
  var headerValues = [];
  var headerNotes = [];
  var hasHeader = false;

  if (sheet.getLastColumn() > 0) {
    var range = sheet.getRange(1, 1, 1, lastCol);
    headerValues = range.getValues()[0];
    headerNotes = range.getNotes()[0];
  } else {
    for (var i = 0; i < lastCol; i++) {
      headerValues.push("");
      headerNotes.push("");
    }
  }

  for (var j = 0; j < headerValues.length; j++) {
    if (headerValues[j] !== "") {
      hasHeader = true;
      break;
    }
  }

  if (!hasHeader) {
    headerValues = BASE_HEADERS_.concat(keysOrder);
    headerNotes = buildHeaderNotes_(headerValues.length, keysOrder);
    sheet.getRange(1, 1, 1, headerValues.length).setValues([headerValues]);
    sheet.getRange(1, 1, 1, headerNotes.length).setNotes([headerNotes]);
    return buildIncomingColumnMap_(keysOrder, baseLen);
  }

  while (headerValues.length < baseLen) headerValues.push("");
  while (headerNotes.length < headerValues.length) headerNotes.push("");

  for (var baseIndex = 0; baseIndex < baseLen; baseIndex++) {
    if (!headerValues[baseIndex]) headerValues[baseIndex] = BASE_HEADERS_[baseIndex];
  }

  var keyToCol = {};
  for (var colIndex = baseLen; colIndex < headerValues.length; colIndex++) {
    var existingKey = headerKeyFromNote_(headerNotes[colIndex]);

    if (!existingKey) {
      existingKey = keysOrder[colIndex - baseLen] || String(headerValues[colIndex] || "").trim();
      if (existingKey) headerNotes[colIndex] = HEADER_KEY_PREFIX_ + existingKey;
    }

    if (existingKey && !keyToCol[existingKey]) {
      keyToCol[existingKey] = colIndex + 1;
    }
  }

  for (var incomingIndex = 0; incomingIndex < keysOrder.length; incomingIndex++) {
    var key = keysOrder[incomingIndex];
    if (keyToCol[key]) continue;

    headerValues.push(key);
    headerNotes.push(HEADER_KEY_PREFIX_ + key);
    keyToCol[key] = headerValues.length;
  }

  sheet.getRange(1, 1, 1, headerValues.length).setValues([headerValues]);
  sheet.getRange(1, 1, 1, headerNotes.length).setNotes([headerNotes]);

  return keyToCol;
}

function getSheetHeaderInfo_(sheet) {
  var width = Math.max(sheet.getLastColumn(), BASE_HEADERS_.length);
  var values = [];
  var notes = [];

  if (sheet.getLastColumn() > 0) {
    var range = sheet.getRange(1, 1, 1, width);
    values = range.getValues()[0];
    notes = range.getNotes()[0];
  } else {
    for (var i = 0; i < width; i++) {
      values.push("");
      notes.push("");
    }
  }

  var headerMap = {};
  for (var col = 0; col < values.length; col++) {
    var headerName = normalizeHeaderName_(values[col]);
    if (headerName && !headerMap[headerName]) {
      headerMap[headerName] = col + 1;
    }
  }

  return {
    values: values,
    notes: notes,
    headerMap: headerMap
  };
}

function parseOrderedFormData_(raw) {
  var keysOrder = [];
  var valuesMap = {};
  if (!raw) return { keysOrder: keysOrder, valuesMap: valuesMap };

  var parts = raw.split("&");
  for (var i = 0; i < parts.length; i++) {
    var part = parts[i];
    if (!part) continue;

    var eq = part.indexOf("=");
    var kEnc = (eq >= 0) ? part.slice(0, eq) : part;
    var vEnc = (eq >= 0) ? part.slice(eq + 1) : "";

    var key = safeDecodeURIComponent_(kEnc.replace(/\+/g, " "));
    var val = safeDecodeURIComponent_(vEnc.replace(/\+/g, " "));

    var m = key.match(/^form_data\[(.+)\]$/);
    if (!m) continue;

    // "form34-6][0" / "form34-6][0]" を "form34-6" に正規化
    var innerKey = m[1].replace(/\]\[\d+\]?$/g, "");

    if (!valuesMap[innerKey]) valuesMap[innerKey] = [];
    if (val !== "") valuesMap[innerKey].push(val);

    if (keysOrder.indexOf(innerKey) === -1) keysOrder.push(innerKey);
  }

  return { keysOrder: keysOrder, valuesMap: valuesMap };
}

function sheetNameFromFormName_(formName) {
  var prefix = "form_";
  var maxLen = 100;

  var name = String(formName)
    .replace(/:/g, "：")
    .replace(/[\\\/\?\*\[\]]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (!name) name = "unknown";

  var allow = maxLen - prefix.length;
  if (name.length > allow) name = name.slice(0, allow).trim();

  return prefix + name;
}

function getOrCreateSheet_(ss, name) {
  return ss.getSheetByName(name) || ss.insertSheet(name);
}

function fmt_(d) {
  return Utilities.formatDate(d, TIMEZONE_, "yyyy-MM-dd HH:mm:ss");
}

function resolveSentAt_(params, payload) {
  var dateValue = pickFirstNonEmpty_([
    params.date,
    payload.date,
    getNestedValue_(payload, ["user_data", "date"])
  ]);
  if (dateValue) return String(dateValue);

  var unixtime = pickFirstNonEmpty_([
    params.unixtime,
    payload.unixtime,
    getNestedValue_(payload, ["user_data", "unixtime"])
  ]);
  if (unixtime) return fmt_(new Date(Number(unixtime) * 1000));

  return fmt_(new Date());
}

function safeDecodeURIComponent_(value) {
  try {
    return decodeURIComponent(value);
  } catch (err) {
    return value;
  }
}

function buildHeaderNotes_(length, keysOrder) {
  var notes = [];
  for (var i = 0; i < length; i++) {
    if (i < BASE_HEADERS_.length) {
      notes.push("");
      continue;
    }

    var key = keysOrder[i - BASE_HEADERS_.length] || "";
    notes.push(key ? HEADER_KEY_PREFIX_ + key : "");
  }
  return notes;
}

function buildIncomingColumnMap_(keysOrder, baseLen) {
  var keyToCol = {};
  for (var i = 0; i < keysOrder.length; i++) {
    keyToCol[keysOrder[i]] = baseLen + i + 1;
  }
  return keyToCol;
}

function headerKeyFromNote_(note) {
  if (!note || note.indexOf(HEADER_KEY_PREFIX_) !== 0) return "";
  return note.slice(HEADER_KEY_PREFIX_.length);
}

function setRowValueByHeaderName_(row, headerInfo, headerName, value) {
  var col = findHeaderColumn_(headerInfo, headerName);
  if (!col) return false;

  row[col - 1] = value;
  return true;
}

function applySpecialSheetFieldMapping_(sheet, headerInfo, row, valuesMap) {
  if (sheet.getName() !== SPECIAL_SHEET_8_NAME_) return;

  for (var formLabel in SPECIAL_FORM_HEADER_MAP_) {
    if (!SPECIAL_FORM_HEADER_MAP_.hasOwnProperty(formLabel)) continue;

    var headerName = SPECIAL_FORM_HEADER_MAP_[formLabel];
    var col = findHeaderColumn_(headerInfo, headerName);
    if (!col) continue;

    var key = findFormKeyByLabel_(valuesMap, formLabel);
    if (!key) continue;

    row[col - 1] = (valuesMap[key] || []).join("\n");
  }
}

function applySpecialSheetStatus_(sheet, headerInfo, row, uid) {
  if (sheet.getName() !== SPECIAL_SHEET_8_NAME_) return;

  var duplicateState = getDuplicateStateByUid_(sheet, headerInfo, uid);
  if (!duplicateState.statusCol) {
    throw new Error("form_8 シートで uid 列または 1S 列が見つかりません。1行目を確認してください。");
  }

  var shouldUsePlanned = !duplicateState.isDuplicate || duplicateState.shouldPromoteToPlanned;
  row[duplicateState.statusCol - 1] = shouldUsePlanned ? SPECIAL_STATUS_PLANNED_ : SPECIAL_STATUS_DUPLICATE_;

  var ownerCol = findHeaderColumn_(headerInfo, SPECIAL_OWNER_HEADER_);
  if (ownerCol && shouldUsePlanned) {
    row[ownerCol - 1] = SPECIAL_OWNER_SHO_;
  }
}

function applyDuplicateStatusToSheet_(sheet) {
  var headerInfo = getSheetHeaderInfo_(sheet);
  var uidCol = findHeaderColumn_(headerInfo, "uid");
  var statusCol = findHeaderColumn_(headerInfo, SPECIAL_STATUS_HEADER_);
  var ownerCol = findHeaderColumn_(headerInfo, SPECIAL_OWNER_HEADER_);
  if (!uidCol || !statusCol) {
    throw new Error("uid 列または 1S 列が見つかりません。1行目を確認してください。");
  }

  var lastRow = sheet.getLastRow();
  if (lastRow <= 1) {
    return {
      targetRows: 0,
      duplicateRows: 0,
      plannedRows: 0,
      keptRows: 0
    };
  }

  var width = Math.max(sheet.getLastColumn(), headerInfo.values.length);
  var values = sheet.getRange(2, 1, lastRow - 1, width).getValues();
  var seen = {};
  var statusValues = [];
  var ownerValues = [];
  var duplicateRows = 0;
  var plannedRows = 0;
  var keptRows = 0;

  for (var i = 0; i < values.length; i++) {
    var row = values[i];
    var uid = normalizeUid_(row[uidCol - 1]);
    var currentStatus = normalizeStatus_(row[statusCol - 1]);
    var nextStatus = currentStatus;
    var currentOwner = ownerCol ? String(row[ownerCol - 1] || "").trim() : "";
    var nextOwner = currentOwner;

    if (uid) {
      if (!seen[uid]) {
        seen[uid] = {
          hasActive: false
        };
      }

      if (seen[uid].hasActive) {
        nextStatus = SPECIAL_STATUS_DUPLICATE_;
        duplicateRows += 1;
      } else {
        if (!currentStatus || currentStatus === SPECIAL_STATUS_DUPLICATE_) {
          nextStatus = SPECIAL_STATUS_PLANNED_;
          if (ownerCol) nextOwner = SPECIAL_OWNER_SHO_;
          seen[uid].hasActive = true;
          plannedRows += 1;
        } else if (isActiveFirstStepStatus_(currentStatus)) {
          seen[uid].hasActive = true;
          keptRows += 1;
        } else {
          keptRows += 1;
        }
      }
    } else {
      keptRows += 1;
    }

    statusValues.push([nextStatus]);
    if (ownerCol) ownerValues.push([nextOwner]);
  }

  sheet.getRange(2, statusCol, statusValues.length, 1).setValues(statusValues);
  if (ownerCol) {
    sheet.getRange(2, ownerCol, ownerValues.length, 1).setValues(ownerValues);
  }

  return {
    targetRows: values.length,
    duplicateRows: duplicateRows,
    plannedRows: plannedRows,
    keptRows: keptRows
  };
}

function getDuplicateStateByUid_(sheet, headerInfo, uid) {
  var uidCol = findHeaderColumn_(headerInfo, "uid");
  var statusCol = findHeaderColumn_(headerInfo, SPECIAL_STATUS_HEADER_);
  if (!uidCol || !statusCol) {
    return {
      uidCol: uidCol,
      statusCol: statusCol,
      isDuplicate: false,
      shouldPromoteToPlanned: false
    };
  }

  var normalizedUid = normalizeUid_(uid);
  if (!normalizedUid) {
    return {
      uidCol: uidCol,
      statusCol: statusCol,
      isDuplicate: false,
      shouldPromoteToPlanned: false
    };
  }

  var lastRow = sheet.getLastRow();
  if (lastRow <= 1) {
    return {
      uidCol: uidCol,
      statusCol: statusCol,
      isDuplicate: false,
      shouldPromoteToPlanned: false
    };
  }

  var width = Math.max(uidCol, statusCol);
  var values = sheet.getRange(2, 1, lastRow - 1, width).getValues();
  var hasMatch = false;
  var hasActiveExisting = false;

  for (var i = 0; i < values.length; i++) {
    if (normalizeUid_(values[i][uidCol - 1]) === normalizedUid) {
      hasMatch = true;
      if (isActiveFirstStepStatus_(values[i][statusCol - 1])) {
        hasActiveExisting = true;
        break;
      }
    }
  }

  return {
    uidCol: uidCol,
    statusCol: statusCol,
    isDuplicate: hasMatch,
    shouldPromoteToPlanned: hasMatch && !hasActiveExisting
  };
}

function normalizeHeaderName_(value) {
  return String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
}

function findHeaderColumn_(headerInfo, headerName) {
  var normalized = normalizeHeaderName_(headerName);
  var aliases = HEADER_ALIASES_[normalized] || [headerName];

  for (var i = 0; i < aliases.length; i++) {
    var col = headerInfo.headerMap[normalizeHeaderName_(aliases[i])];
    if (col) return col;
  }

  return 0;
}

function findFormKeyByLabel_(valuesMap, label) {
  var normalizedLabel = normalizeFormLabel_(label);
  for (var key in valuesMap) {
    if (!valuesMap.hasOwnProperty(key)) continue;
    if (normalizeFormLabel_(key) === normalizedLabel) return key;
  }
  return "";
}

function normalizeFormLabel_(value) {
  return String(value || "").replace(/\s+/g, "").trim();
}

function normalizeUid_(value) {
  return String(value || "").replace(/\s+/g, "").trim();
}

function normalizeStatus_(value) {
  return String(value || "").trim();
}

function isActiveFirstStepStatus_(value) {
  var status = normalizeStatus_(value);
  return status === SPECIAL_STATUS_PLANNED_ || status === SPECIAL_STATUS_DONE_;
}

function parseRequestPayload_(raw) {
  if (!raw) return {};

  try {
    return JSON.parse(raw);
  } catch (err) {
    return parseNestedBody_(raw);
  }
}

function parseNestedBody_(raw) {
  var payload = {};
  var parts = String(raw || "").split("&");

  for (var i = 0; i < parts.length; i++) {
    var part = parts[i];
    if (!part) continue;

    var eq = part.indexOf("=");
    var kEnc = (eq >= 0) ? part.slice(0, eq) : part;
    var vEnc = (eq >= 0) ? part.slice(eq + 1) : "";
    var key = safeDecodeURIComponent_(kEnc.replace(/\+/g, " "));
    var value = safeDecodeURIComponent_(vEnc.replace(/\+/g, " "));
    assignNestedValue_(payload, key, value);
  }

  return payload;
}

function assignNestedValue_(target, key, value) {
  var normalized = String(key || "").replace(/\]/g, "");
  var segments = normalized.split("[").filter(Boolean);
  if (!segments.length) return;

  var current = target;
  for (var i = 0; i < segments.length - 1; i++) {
    var segment = segments[i];
    if (!current[segment] || typeof current[segment] !== "object") {
      current[segment] = {};
    }
    current = current[segment];
  }

  current[segments[segments.length - 1]] = value;
}

function getNestedValue_(target, pathSegments) {
  var current = target;

  for (var i = 0; i < pathSegments.length; i++) {
    if (!current || typeof current !== "object") return "";
    current = current[pathSegments[i]];
  }

  return current == null ? "" : current;
}

function pickFirstNonEmpty_(candidates) {
  for (var i = 0; i < candidates.length; i++) {
    var value = candidates[i];
    if (value !== null && value !== undefined && String(value).trim() !== "") {
      return value;
    }
  }

  return "";
}

function extractReferrerCode_(params, payload) {
  return normalizeUid_(pickFirstNonEmpty_([
    params.ref_code,
    params.free2,
    params["user_data[ref_code]"],
    params["user_data[free2]"],
    params["form_data[ref_code]"],
    params["form_data[free2]"],
    payload.ref_code,
    payload.free2,
    getNestedValue_(payload, ["user_data", "ref_code"]),
    getNestedValue_(payload, ["user_data", "free2"]),
    getNestedValue_(payload, ["form_data", "ref_code"]),
    getNestedValue_(payload, ["form_data", "free2"])
  ]));
}

function resolveReferrerName_(spreadsheet, refCode) {
  if (!refCode) return REFERRER_NONE_TEXT_;

  var masterSheet = spreadsheet.getSheetByName(REFERRER_MASTER_SHEET_NAME_);
  if (!masterSheet) {
    throw new Error("紹介者マスタが見つかりません: " + REFERRER_MASTER_SHEET_NAME_);
  }

  var lastRow = masterSheet.getLastRow();
  var lastColumn = masterSheet.getLastColumn();
  if (lastRow < 2 || lastColumn < 1) return REFERRER_NONE_TEXT_;

  var values = masterSheet.getRange(1, 1, lastRow, lastColumn).getDisplayValues();
  var headerMap = buildHeaderMapFromValues_(values[0] || []);
  var codeCol = findHeaderIndex_(headerMap, REFERRER_CODE_HEADERS_, 3);
  var nameCol = findHeaderIndex_(headerMap, REFERRER_NAME_HEADERS_, 2);

  for (var i = 1; i < values.length; i++) {
    var row = values[i];
    if (normalizeUid_(row[codeCol - 1]) === refCode) {
      return normalizeStatus_(row[nameCol - 1]) || REFERRER_NONE_TEXT_;
    }
  }

  return REFERRER_NONE_TEXT_;
}

function buildHeaderMapFromValues_(headerValues) {
  var headerMap = {};

  for (var i = 0; i < headerValues.length; i++) {
    var normalized = normalizeHeaderName_(headerValues[i]);
    if (normalized && !headerMap[normalized]) {
      headerMap[normalized] = i + 1;
    }
  }

  return headerMap;
}

function findHeaderIndex_(headerMap, candidates, fallbackIndex) {
  for (var i = 0; i < candidates.length; i++) {
    var col = headerMap[normalizeHeaderName_(candidates[i])];
    if (col) return col;
  }

  return fallbackIndex;
}

function debugLogError_(debugSheet, err, raw) {
  debugSheet.appendRow([
    fmt_(new Date()),
    "ERROR",
    String(err),
    raw
  ]);
}
